/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['statsmodels','r-base']:
  url=f'https://quay.io/v2/biocontainers/{repo}/tags/list?n=10'
  try:
    with urllib.request.urlopen(url, timeout=30) as r: d=json.load(r)
    print(repo, d.get('tags',[])[:10])
  except Exception as e: print(repo, type(e).__name__, e)
PY"

